from file_repository import FileRepository
from path_utils import allow_extension, collapse_dots, validate_download_path


class DownloadService:
    def __init__(self, repo: FileRepository) -> None:
        self._repo = repo
        self._allowed_ext = {"txt", "csv", "json", "md"}

    def set_allowed_extensions(self, values: set[str]) -> None:
        self._allowed_ext = {item.lower().strip() for item in values if item.strip()}

    def can_download(self, rel_path: str) -> dict[str, Any]:
        checked = validate_download_path(self._repo.root, rel_path)
        if not checked.get("ok"):
            return {"ok": False, "reason": "forbidden"}
        if not allow_extension(rel_path, self._allowed_ext):
            return {"ok": False, "reason": "bad_extension"}
        return {"ok": True, "reason": "allowed", "candidate": checked.get("candidate", "")}

    def read(self, rel_path: str) -> dict[str, Any]:
        gate = self.can_download(rel_path)
        if not gate.get("ok"):
            return {"ok": False, "status": 403, "reason": gate.get("reason", "forbidden")}
        canonical_rel = collapse_dots(rel_path)
        content = self._repo.get(canonical_rel)
        if content is None:
            return {"ok": False, "status": 404, "reason": "not_found"}
        return {"ok": True, "status": 200, "reason": "downloaded", "content": content}

    def describe(self) -> dict[str, Any]:
        return {
            "root": self._repo.root,
            "allowed_extensions": sorted(self._allowed_ext),
            "file_count": self._repo.count(),
        }

    def list_downloadable(self, prefix: str = "") -> list[str]:
        rows = self._repo.find_by_prefix(prefix)
        return [row for row in rows if allow_extension(row, self._allowed_ext)]

    def audit_entry(self, rel_path: str, success: bool) -> dict[str, Any]:
        return {
            "path": rel_path,
            "success": bool(success),
            "root": self._repo.root,
            "allowed": allow_extension(rel_path, self._allowed_ext),
        }

    def dry_run(self, rel_path: str) -> dict[str, Any]:
        gate = self.can_download(rel_path)
        if not gate.get("ok"):
            return {"ok": False, "reason": gate.get("reason", "forbidden"), "would_read": False}
        return {"ok": True, "reason": "allowed", "would_read": self._repo.exists(rel_path)}

    def preflight(self, rel_path: str) -> tuple[bool, str]:
        gate = self.can_download(rel_path)
        return bool(gate.get("ok")), str(gate.get("reason", "forbidden"))

    def preview(self, rel_path: str, size: int = 32) -> dict[str, Any]:
        result = self.read(rel_path)
        if not result.get("ok"):
            return {"ok": False, "reason": result.get("reason", "forbidden"), "preview": ""}
        content = str(result.get("content", ""))
        return {"ok": True, "reason": "preview", "preview": content[: max(0, int(size))]}

    def explain_path(self, rel_path: str) -> dict[str, Any]:
        gate = self.can_download(rel_path)
        return {
            "requested": rel_path,
            "normalized": collapse_dots(rel_path),
            "allowed": bool(gate.get("ok")),
            "reason": gate.get("reason", "forbidden"),
        }

    def allowed_extensions(self) -> list[str]:
        return sorted(self._allowed_ext)

    def file_exists(self, rel_path: str) -> bool:
        normalized = collapse_dots(rel_path)
