from path_utils import collapse_dots, normalize_user_path


class FileRepository:
    def __init__(self, root: str) -> None:
        self._root = normalize_user_path(root).rstrip("/")
        self._files: dict[str, str] = {}

    @property
    def root(self) -> str:
        return self._root

    def put(self, rel_path: str, content: str) -> None:
        key = normalize_user_path(rel_path).lstrip("/")
        if not key:
            raise ValueError("path required")
        self._files[key] = str(content)

    def get(self, rel_path: str) -> str | None:
        key = collapse_dots(rel_path).lstrip("/")
        if not key:
            return None
        return self._files.get(key)

    def exists(self, rel_path: str) -> bool:
        return self.get(rel_path) is not None

    def delete(self, rel_path: str) -> bool:
        key = normalize_user_path(rel_path).lstrip("/")
        if key in self._files:
            del self._files[key]
            return True
        return False

    def list_paths(self) -> list[str]:
        return sorted(self._files.keys())

    def count(self) -> int:
        return len(self._files)

    def seed(self, rows: dict[str, str]) -> None:
        for path, content in rows.items():
            self.put(path, content)

    def snapshot(self) -> dict[str, str]:
        return dict(self._files)

    def stats(self) -> dict[str, Any]:
        return {
            "root": self._root,
            "count": self.count(),
            "paths": self.list_paths(),
        }

    def find_by_prefix(self, prefix: str) -> list[str]:
        target = normalize_user_path(prefix).lstrip("/")
        return [p for p in self.list_paths() if p.startswith(target)]

    def move(self, old_path: str, new_path: str) -> bool:
        old_key = normalize_user_path(old_path).lstrip("/")
        new_key = normalize_user_path(new_path).lstrip("/")
        if not old_key or not new_key or old_key not in self._files:
            return False
        self._files[new_key] = self._files[old_key]
        del self._files[old_key]
        return True

    def append(self, rel_path: str, extra: str) -> None:
        current = self.get(rel_path) or ""
        self.put(rel_path, current + str(extra))

    def replace(self, rel_path: str, content: str) -> bool:
        key = collapse_dots(rel_path).lstrip("/")
        if key not in self._files:
            return False
        self._files[key] = str(content)
        return True

    def copy(self, from_path: str, to_path: str) -> bool:
        source = collapse_dots(from_path).lstrip("/")
        target = collapse_dots(to_path).lstrip("/")
        if not source or not target or source not in self._files:
            return False
        self._files[target] = self._files[source]
        return True

    def path_info(self, rel_path: str) -> dict[str, Any]:
        key = collapse_dots(rel_path).lstrip("/")
        return {
            "requested": rel_path,
            "normalized": key,
            "exists": key in self._files,
            "size": len(self._files.get(key, "")),
        }

