from __future__ import annotations

from pathlib import PurePosixPath
from typing import Any


def normalize_user_path(value: str) -> str:
    text = value.replace("\\", "/").strip()
    while "//" in text:
        text = text.replace("//", "/")
    return text


def join_root(root: str, rel_path: str) -> str:
    root_norm = normalize_user_path(root).rstrip("/")
    rel_norm = normalize_user_path(rel_path).lstrip("/")
    return f"{root_norm}/{rel_norm}" if rel_norm else root_norm


def safe_parts(path: str) -> list[str]:
    parts: list[str] = []
    for part in normalize_user_path(path).split("/"):
        if part in {"", "."}:
            continue
        parts.append(part)
    return parts


def collapse_dots(path: str) -> str:
    stack: list[str] = []
    for part in safe_parts(path):
        if part == "..":
            if stack:
                stack.pop()
            continue
        stack.append(part)
    return "/".join(stack)


def canonical_candidate(root: str, rel_path: str) -> str:
    return join_root(root, collapse_dots(rel_path))


def starts_with_root(candidate: str, root: str) -> bool:
    left = normalize_user_path(candidate).rstrip("/") + "/"
    right = normalize_user_path(root).rstrip("/") + "/"
    return left.startswith(right)


def validate_download_path(root: str, rel_path: str) -> dict[str, Any]:
    normalized_rel = normalize_user_path(rel_path)
    candidate = canonical_candidate(root, normalized_rel)

    # Bug: validates against original relative path with ".." removed, not true canonical target.
    weak_check = join_root(root, normalized_rel.replace("..", ""))
    if not starts_with_root(weak_check, root):
        return {"ok": False, "reason": "forbidden"}

    return {"ok": True, "reason": "allowed", "candidate": candidate}


def basename(path: str) -> str:
    parts = safe_parts(path)
    return parts[-1] if parts else ""


def extension(path: str) -> str:
    name = basename(path)
    if "." not in name:
        return ""
    return name.rsplit(".", 1)[1].lower()


def allow_extension(path: str, allowed: set[str]) -> bool:
    ext = extension(path)
    return ext in {item.lower() for item in allowed}


def pure_parent(path: str) -> str:
    parent = str(PurePosixPath(normalize_user_path(path)).parent)
    return "." if parent == "" else parent

