from __future__ import annotations

from typing import Any

from download_service import DownloadService


def _path(payload: dict[str, Any]) -> str:
    return str(payload.get("path", "")).strip()


def _request_id(payload: dict[str, Any]) -> str:
    return str(payload.get("request_id", "")).strip() or "req-unknown"


def _actor(payload: dict[str, Any]) -> str:
    actor = payload.get("actor", {})
    if isinstance(actor, dict):
        return str(actor.get("user_id", "")).strip() or "anonymous"
    return "anonymous"


def handle_download(payload: dict[str, Any], service: DownloadService) -> dict[str, Any]:
    rel_path = _path(payload)
    request_id = _request_id(payload)
    actor = _actor(payload)
    if not rel_path:
        return {"ok": False, "status": 400, "reason": "missing_path", "request_id": request_id}

    result = service.read(rel_path)
    return {
        "ok": bool(result.get("ok")),
        "status": int(result.get("status", 500)),
        "reason": str(result.get("reason", "error")),
        "content": result.get("content", ""),
        "request_id": request_id,
        "actor": actor,
    }


def build_request(path: str, request_id: str = "req-1", actor_id: str = "user-1") -> dict[str, Any]:
    return {
        "path": path,
        "request_id": request_id,
        "actor": {"user_id": actor_id},
    }


def describe_request(payload: dict[str, Any]) -> dict[str, str]:
    return {
        "path": _path(payload),
        "request_id": _request_id(payload),
        "actor": _actor(payload),
    }


def endpoint_metadata() -> dict[str, Any]:
    return {
        "name": "download",
        "version": "1",
        "required_fields": ["path"],
        "optional_fields": ["request_id", "actor.user_id"],
    }


def result_summary(result: dict[str, Any]) -> str:
    return f"{result.get('status', 0)}:{result.get('reason', 'unknown')}:{result.get('request_id', '')}"


def is_client_error(result: dict[str, Any]) -> bool:
    status = int(result.get("status", 500))
    return 400 <= status < 500


def is_server_error(result: dict[str, Any]) -> bool:
    status = int(result.get("status", 500))
    return status >= 500


def audit_payload(payload: dict[str, Any]) -> dict[str, Any]:
    description = describe_request(payload)
    return {
        "request_id": description["request_id"],
        "actor": description["actor"],
        "path": description["path"],
        "path_length": len(description["path"]),
        "has_extension": "." in description["path"].split("/")[-1],
    }


def merge_request(base: dict[str, Any], overrides: dict[str, Any]) -> dict[str, Any]:
    merged = dict(base)
    merged.update(overrides)
    return merged

